INSERT INTO interpretation_templates (condition_key, condition_value, category, title, summary, content, weight, is_active) VALUES
('day_pillar', '갑진', 'general', '갑진일주 · 총운', '봄의 비옥한 대지에 깊숙이 뿌리를 내린 푸른 나무처럼 포용력과 성장 욕구가 넘치는 기질입니다.', '갑목의 진취적인 기상과 진토의 거대한 대지가 만나 백호살의 기운을 띠며, 남에게 굽히지 않는 강한 주관을 지녔습니다. 이상이 높고 스케일이 커서 큰 무대를 지향하며, 역경 속에서도 끝내 싹을 틔우는 불굴의 의지가 돋보이는 외강내강형의 성향을 보여줍니다.', 70, true),
('day_pillar', '갑진', 'career', '갑진일주 · 직업', '스케일이 크고 주도권을 행사하는 건축, 부동산, 군검경, 대형 사업 분야에 적합합니다.', '거대한 땅을 호령하는 목극토의 편재성을 띠어 조직에 얽매이기보다 독립적인 사업이나 프로젝트의 리더로 나설 때 눈부신 역량을 발휘합니다. 강인한 추진력을 요구하는 토목, 생살여탈권을 쥐는 공직, 큰 자금이 움직이는 금융 분야에서 탁월한 수완을 보여주기 좋습니다.', 70, true),
('day_pillar', '갑진', 'love', '갑진일주 · 연애', '가벼운 만남을 꺼리고 듬직하게 상대를 보호하려 하나, 주장이 지나치게 강할 수 있습니다.', '상대방을 포용하고 책임지려는 태도가 강해 한 번 맺은 인연에 헌신하는 든든함을 보여줍니다. 하지만 타인의 의견에 쉽게 꺾이지 않는 자존심 탓에 연애 과정에서 다소 권위적으로 비칠 수 있으므로, 서로의 차이를 인정하고 부드럽게 양보하는 자세를 기르는 것이 중요합니다.', 70, true),
('day_pillar', '갑진', 'wealth', '갑진일주 · 재물', '커다란 야망을 바탕으로 굵직한 부동산이나 실물 자산을 통해 거대한 부를 좇는 성향입니다.', '작은 이익을 좇기보다는 통 크게 판을 벌려 단숨에 상당한 재물을 거머쥐려는 배포가 두드러집니다. 진토라는 거대한 흙의 창고를 활용하여 투기성 짙은 사업보다는 땅과 부동산, 건물 등 묵직한 실물에 자산을 묶어두는 것이 재물을 지키고 증식하는 가장 안전한 길입니다.', 70, true),
('day_pillar', '갑진', 'health', '갑진일주 · 건강', '강한 에너지 발산으로 인해 소화기 계통과 간 기능 관리에 신경 쓰면 좋습니다.', '지나친 스트레스와 승부욕으로 인해 간과 위장에 열이 누적되어 소화 불량이나 신경성 위장병을 겪기 쉬운 구조입니다. 과식과 폭음을 멀리하고 긴장을 이완시키는 명상이나 가벼운 유산소 운동으로 몸의 화기를 덜어내며 수분을 충분히 보충하는 습관이 몹시 이롭습니다.', 70, true),
('day_pillar', '을사', 'general', '을사일주 · 총운', '초여름의 화려한 꽃처럼 다재다능하며 맑고 밝은 에너지를 발산하는 매력적인 기질입니다.', '여린 을목이 뜨거운 사화를 만나 상관의 기운을 활짝 피우는 목욕(沐浴)의 형태로, 감수성이 풍부하고 대중의 시선을 사로잡는 능력이 탁월합니다. 겉보기엔 부드럽고 상냥하여 사람들과 잘 어울리지만 내면에는 빠른 눈치와 치밀한 판단력을 숨기고 있는 야무진 성향입니다.', 70, true),
('day_pillar', '을사', 'career', '을사일주 · 직업', '뛰어난 언변과 미적 감각을 뽐내는 방송, 언론, 예술, 교육, 서비스 분야에 훌륭하게 맞습니다.', '자신을 드러내고 표현하는 재주가 뛰어나 아나운서, 강사, 연예인, 디자인 분야에서 압도적인 존재감을 발휘합니다. 화술이 뛰어나고 상황 대처 능력이 기민하므로 남을 설득하는 영업이나 기획, 외교 업무에서도 대인 관계를 원활하게 이끌어가는 재주꾼으로 인정받습니다.', 70, true),
('day_pillar', '을사', 'love', '을사일주 · 연애', '감정 표현이 풍부하고 매력적이어서 이성에게 인기가 높으나 싫증을 내기 쉬운 편입니다.', '낭만적이고 유쾌한 데이트를 주도하며 뛰어난 화술로 연인의 마음을 금세 사로잡는 매력이 돋보입니다. 그러나 구속받는 것을 견디지 못하고 새로운 자극을 좇는 성향이 있어 관계가 흔들릴 우려가 있으니 인내심을 갖고 한 사람에게 진지하게 헌신하려는 책임감이 요구됩니다.', 70, true),
('day_pillar', '을사', 'wealth', '을사일주 · 재물', '다방면의 재능과 화려한 언변을 무기로 끊임없이 활동하며 재물을 모으는 흐름입니다.', '자신의 창의적인 아이디어나 기술을 현금으로 직결시키는 수완이 남다르며 평생 의식주가 풍족한 흐름을 가집니다. 다만 꾸미는 것을 좋아하고 유행에 민감해 지출의 규모가 덩달아 커지기 쉬우므로, 수입의 일부를 저축이나 문서로 단단히 묶어두는 경제 관념이 필수적입니다.', 70, true),
('day_pillar', '을사', 'health', '을사일주 · 건강', '에너지를 쉽게 소진하므로 심혈관 질환과 호흡기 건강 유지에 유의하면 좋습니다.', '열기를 지나치게 발산하는 구조로 인해 신경이 예민해지거나 심장 질환, 안구 건조증 등에 시달리기 쉽습니다. 몸의 수분이 빠르게 마를 수 있으니 충분한 수분 섭취를 생활화하고 심신을 차분하게 가라앉히는 다도나 산책 등 정적인 휴식으로 균형을 맞추는 것이 바람직합니다.', 70, true),
('day_pillar', '병오', 'general', '병오일주 · 총운', '한여름 뙤약볕의 정오처럼 맹렬하고 열정적이며 매사에 거침없이 돌진하는 기질입니다.', '병화와 오화가 만난 간여지동이자 양인의 구조로 천하를 호령하는 극강의 카리스마와 독립심을 자랑합니다. 불꽃처럼 화끈하고 뒤끝이 없으며 한번 마음먹은 일은 타협 없이 끝까지 밀어붙이는 불굴의 의지가 돋보이나 다소 직설적이고 불같은 성미를 숨기기 어렵습니다.', 70, true),
('day_pillar', '병오', 'career', '병오일주 · 직업', '강력한 통솔력과 승부욕을 요하는 군검경, 스포츠, 정치, 특수 기술 분야에 매우 적합합니다.', '누군가의 밑에서 지시를 받는 것을 극도로 꺼리며 독자적인 영역에서 사람들을 이끄는 리더로 나설 때 탁월한 역량을 뽐냅니다. 생사여탈권을 쥐는 공직, 경찰, 혹은 극한의 에너지를 쏟아붓는 스포츠나 대규모 사업에서 압도적인 성취와 명예를 거머쥐기 좋은 구조입니다.', 70, true),
('day_pillar', '병오', 'love', '병오일주 · 연애', '열정적이고 솔직하게 감정을 표현하며 상대방을 적극적으로 리드하지만 지배욕이 강합니다.', '마음에 드는 상대에게 주저 없이 돌진하여 관계를 쟁취하는 편이나, 자기주장이 강하고 상대방을 통제하려는 성향이 짙어 잦은 마찰을 빚을 수 있습니다. 다툼이 발생하면 타협을 모르고 폭발하는 경향이 있으니, 상대의 입장을 부드럽게 배려하는 유연한 태도가 관계의 핵심입니다.', 70, true),
('day_pillar', '병오', 'wealth', '병오일주 · 재물', '스케일이 남달라 큰돈을 굴리는 배포를 가졌지만 재산의 기복 역시 심하게 나타나는 흐름입니다.', '작은 이익에 얽매이지 않고 큰 사업이나 투자에 뛰어들어 단숨에 거대한 수익을 내는 수완이 출중합니다. 하지만 충동적이고 과시적인 지출이 뒤따라 돈이 순식간에 빠져나갈 위험이 크므로, 굴린 현금을 즉각 부동산이나 안정적인 자산에 투자해 묶어두는 지혜가 절대적으로 필요합니다.', 70, true),
('day_pillar', '병오', 'health', '병오일주 · 건강', '화기가 극도로 강해 심혈관계 및 안과 질환, 신경 쇠약 방지에 신경 쓰면 좋습니다.', '불의 기운이 치솟아 혈압이 오르거나 심장에 무리가 가고 수분이 말라 신장 기능이 저하되기 쉬운 체질입니다. 과격한 운동보다는 수영 등 물과 가까이하는 활동이 유익하며 열을 식혀줄 수 있는 차분한 명상과 충분한 수면으로 화기를 억누르는 것이 건강 관리의 최우선입니다.', 70, true),
('day_pillar', '정미', 'general', '정미일주 · 총운', '한여름 밤의 용광로처럼 조용한 겉모습 이면에 뜨거운 집념과 예리함을 숨긴 기질입니다.', '은은한 정화가 건조하고 뜨거운 미토 위에서 강렬한 열기를 뿜어내는 구조로 겉보기엔 부드럽고 다정하지만 속은 굽히지 않는 고집으로 가득 차 있습니다. 눈치가 빠르고 환경 적응력이 뛰어나며 한 번 결심한 목표는 묵묵히 밤을 새워 이루고 마는 극강의 인내력을 보여줍니다.', 70, true),
('day_pillar', '정미', 'career', '정미일주 · 직업', '뛰어난 집중력과 전문성을 요구하는 기술직, 의료, 상담, 기획, 교육 분야에 적합합니다.', '예리한 직관과 분석력을 갖추어 한 분야를 깊게 파고드는 연구원, 엔지니어, 세무사 등에서 대단한 능률을 발휘합니다. 사람의 마음을 꿰뚫어보는 식신의 기운이 발달해 남의 아픔을 보듬는 활인업이나 심리 상담, 종교계 등에서도 훌륭한 성취와 사회적 존경을 얻을 수 있습니다.', 70, true),
('day_pillar', '정미', 'love', '정미일주 · 연애', '세심하게 상대를 배려하고 헌신하지만, 마음속의 잣대가 높아 매우 까다롭고 예민합니다.', '다정다감한 태도로 연인의 호감을 얻으며 진지한 관계를 지향하나, 내면에 감춰진 불같은 기질 탓에 한 번 틀어지면 걷잡을 수 없이 냉정해집니다. 속마음을 혼자 삭이다가 상대에게 예민하게 반응할 수 있으니 평소 긍정적인 대화로 스트레스를 풀고 서로를 포용하려는 노력이 필요합니다.', 70, true),
('day_pillar', '정미', 'wealth', '정미일주 · 재물', '치밀한 계산 능력과 끈질긴 인내를 바탕으로 알뜰하게 실물 자산을 모아가는 실속파입니다.', '돈을 허투루 쓰는 법이 없고 꼼꼼하게 실속을 챙겨 평생에 걸쳐 안정적인 부를 축적하는 데 탁월한 소질이 있습니다. 화려한 투기성 사업보다는 건조한 땅에 열기를 저장하듯 부동산이나 기술 자격증 등을 통해 차곡차곡 재산을 늘려 나가는 보수적인 재테크 방식이 몹시 유리합니다.', 70, true),
('day_pillar', '정미', 'health', '정미일주 · 건강', '열기가 뭉치기 쉬워 호흡기 및 피부 질환, 소화기 계통 건강 관리에 유의하면 좋습니다.', '뜨겁고 메마른 흙의 영향으로 체내 수분이 말라 기관지가 건조해지거나 위염, 변비 등에 노출되기 쉬운 체질입니다. 자극적인 음식을 멀리하고 신선한 채소와 수분을 충분히 보충하며 규칙적인 가벼운 운동으로 땀을 배출해 몸의 긴장을 유연하게 풀어주는 것이 건강을 지키는 비결입니다.', 70, true),
('day_pillar', '무신', 'general', '무신일주 · 총운', '깊은 산속에서 솟아나는 샘물처럼 식록이 풍부하고 다방면에 재주가 많은 여유로운 기질입니다.', '무토의 포용력 넒은 대지가 신금이라는 단단한 바위에서 물을 뿜어내는 식신 역마의 구조로 활동력이 왕성합니다. 매사에 낙천적이고 사람들에게 베풀기를 좋아하며 두뇌 회전이 매우 빠릅니다. 어떠한 난관에도 유연하게 대처하는 적응력과 함께 뛰어난 문장력과 말솜씨를 지녔습니다.', 70, true),
('day_pillar', '무신', 'career', '무신일주 · 직업', '비상한 두뇌와 기획력을 발휘하는 무역, 외교, 유통, 교육 및 요식업 분야에 훌륭하게 맞습니다.', '식신의 길한 기운과 역마살이 결합하여 해외를 오가는 유통업이나 무역, 운수업 등 활동적인 무대에서 크게 성공하기 좋습니다. 가르치는 재주가 남달라 교육자나 학자로도 두각을 나타내며 사람들을 먹여 살리는 요식업이나 기발한 아이디어를 내는 기획 업무에서도 역량이 빛납니다.', 70, true),
('day_pillar', '무신', 'love', '무신일주 · 연애', '재치 있고 다정하게 분위기를 리드하나 자유분방한 성향 탓에 구속받기를 몹시 싫어합니다.', '풍부한 유머 감각과 배려심으로 이성에게 인기가 많으며 연애를 로맨틱하게 이끌어가는 매력이 돋보입니다. 하지만 한곳에 머물지 않으려는 역마의 특성상 상대방에게 지나치게 구속받으면 금세 답답함을 느끼므로 서로의 독립적인 생활을 존중하는 쿨한 관계가 장기적으로 바람직합니다.', 70, true),
('day_pillar', '무신', 'wealth', '무신일주 · 재물', '평생 먹을 복이 마르지 않으며 끊임없는 활동과 수완으로 넉넉한 부를 창출해 내는 흐름입니다.', '남다른 정보력과 번뜩이는 재치로 쉴 새 없이 수익을 만들어내는 경제 관념이 대단히 뛰어납니다. 남들이 놓치는 틈새시장을 파고들어 돈을 벌어들이는 재주가 탁월하나, 활동성이 큰 만큼 지출의 규모도 크니 수입의 일부를 저축이나 부동산으로 묶어두는 꼼꼼한 관리가 뒷받침되어야 합니다.', 70, true),
('day_pillar', '무신', 'health', '무신일주 · 건강', '체력 소모가 많은 편이므로 신경계 피로와 호흡기, 관절 건강 관리에 신경 쓰면 좋습니다.', '외부 활동이 잦고 두뇌를 많이 사용하여 금세 피로해지거나 신경이 날카로워져 두통에 시달릴 수 있습니다. 토생금의 구조상 호흡기나 대장 기능이 예민해지기 쉬으니 맑은 공기를 자주 마시고 적절한 휴식과 수면을 통해 신체의 리듬을 안정적으로 유지하는 습관이 중요합니다.', 70, true),
('day_pillar', '기유', 'general', '기유일주 · 총운', '기름진 옥토에 묻힌 보석처럼 정교한 손재주와 세련된 미적 감각, 비상한 암기력을 지녔습니다.', '기토의 부드러움과 유금의 맑고 예리한 기운이 만나 식신의 총명함을 발산하는 구조입니다. 성품이 온화하고 남을 돕는 데 앞장서지만, 맺고 끊음이 얼음장처럼 명확하여 불합리한 것을 결코 용납하지 않는 차가운 내면을 가졌습니다. 하나를 들으면 열을 아는 영리함이 돋보입니다.', 70, true),
('day_pillar', '기유', 'career', '기유일주 · 직업', '정밀함을 요하는 전문 기술, 의료, 예술, 기획, 금융 분야 등에서 압도적인 능률을 보입니다.', '뛰어난 미적 감각과 섬세한 손재주를 타고나 요리사, 디자이너, 미용사로서 대단한 두각을 나타내며, 치밀한 분석력을 요하는 회계나 세무, 연구직에도 적합합니다. 또한 사람을 치유하는 의사나 약사 등 특수한 자격증을 필요로 하는 전문직에서 사회적인 인정과 명예를 얻기 좋습니다.', 70, true),
('day_pillar', '기유', 'love', '기유일주 · 연애', '세련된 매너로 헌신하지만 잣대가 높아 상대의 단점을 보면 가차 없이 돌아설 수 있습니다.', '다정하고 깔끔한 분위기로 이성의 호감을 사며 연인에게 헌신적으로 배려하는 따뜻함을 지녔습니다. 하지만 완벽을 추구하는 특유의 예민함 탓에 상대방의 사소한 실수에도 실망감을 크게 느끼고 냉정해지는 면모가 있으므로, 너그러운 포용력을 기르는 것이 원만한 관계의 핵심입니다.', 70, true),
('day_pillar', '기유', 'wealth', '기유일주 · 재물', '자신의 뛰어난 기술과 아이디어를 바탕으로 차곡차곡 재산을 쌓아가는 든든한 실속파입니다.', '식신의 기운 덕에 일생 동안 의식주가 풍요로우며 무모한 투기보다는 자신이 가장 잘 아는 전문 분야에서 확실하게 수익을 올리는 흐름을 선호합니다. 돈을 다루는 솜씨가 정교하고 불필요한 낭비를 꺼려 알뜰하게 자산을 증식하며 기술이나 자격증이 곧 재물이 되는 대단히 안정적인 구조입니다.', 70, true),
('day_pillar', '기유', 'health', '기유일주 · 건강', '신경이 예민해지기 쉬우니 소화기 장애와 치아, 관절 등 뼈 건강에 유의하면 좋습니다.', '스트레스를 받으면 흙의 기운이 약해져 위염이나 소화 불량 등에 취약해지고 신경성 편두통에 시달릴 수 있습니다. 관절이나 뼈가 약해질 수 있는 체질이므로 틈틈이 칼슘을 섭취하고 뭉친 근육을 풀어주는 요가 등을 통해 긴장을 이완시키며 심리적 평온을 찾는 것이 건강 관리에 중요합니다.', 70, true),
('day_pillar', '경술', 'general', '경술일주 · 총운', '가을산의 큰 바위처럼 묵직하고 결단력이 뛰어나며 대의명분을 중시하는 강인한 기질입니다.', '경금의 단단함과 술토의 조열함이 만난 괴강살의 구조로 어떠한 외압에도 흔들리지 않는 극강의 주관을 뽐냅니다. 불의를 참지 못하고 정의를 위해 돌진하는 카리스마를 지녔으며 겉으로는 무뚝뚝해 보여도 내면엔 한 번 믿음을 준 사람을 끝까지 책임지는 짙은 의리가 자리 잡고 있습니다.', 70, true),
('day_pillar', '경술', 'career', '경술일주 · 직업', '통솔력과 결단력을 요구하는 군검경, 정치, 토목, 대규모 사업 분야에 훌륭하게 맞습니다.', '편인의 비상한 두뇌와 괴강의 카리스마가 결합하여 남의 밑에서 순응하기보다 독립적으로 큰 프로젝트를 지휘할 때 능력을 크게 인정받습니다. 권력을 다루는 법조계나 생사여탈권을 쥐는 공직, 혹은 거대한 스케일의 건축 및 부동산업에서 압도적인 리더십으로 승부수를 띄우기 좋습니다.', 70, true),
('day_pillar', '경술', 'love', '경술일주 · 연애', '진중하고 책임감 있게 상대를 대하나 지나친 고집으로 인해 상대를 지치게 할 수 있습니다.', '가벼운 만남을 극도로 꺼리고 신뢰를 바탕으로 한 진지한 연애를 지향하며 연인을 듬직하게 지키려는 보호 본능이 강합니다. 하지만 무뚝뚝한 표현 방식과 한 번 화가 나면 꺾이지 않는 자존심 탓에 다툼이 길어질 수 있으니 상대의 감정에 부드럽게 귀 기울이는 포용력을 꼭 길러야 합니다.', 70, true),
('day_pillar', '경술', 'wealth', '경술일주 · 재물', '안정적인 문서와 큰 스케일의 부동산 투자를 통해 막대한 부를 묵직하게 쌓아가는 성향입니다.', '작은 돈에 연연하지 않는 배포를 지녔으며 흙 속에 금을 품은 형상으로 부동산, 문서, 자격증을 통해 큰 재물을 저장하고 묶어두는 데 탁월합니다. 유행을 타는 투기성 사업보다는 안정적이고 덩치가 큰 실물 자산에 장기적으로 투자할 때 잠재된 엄청난 재물복이 폭발적인 성과를 냅니다.', 70, true),
('day_pillar', '경술', 'health', '경술일주 · 건강', '조열한 기운이 뭉치기 쉬우니 대장이나 호흡기, 위장 건강 관리에 각별히 신경 쓰면 좋습니다.', '토생금의 기운이 강하고 수기가 부족해 몸이 건조해지기 쉬우며 변비나 호흡기 질환, 신경성 위장병에 시달릴 우려가 있습니다. 수분을 충분히 보충하고 스트레스를 고집스럽게 안고 가기보다 땀을 내는 야외 활동이나 등산 등으로 신체의 열기를 시원하게 발산하는 것이 건강을 돕습니다.', 70, true),
('day_pillar', '신해', 'general', '신해일주 · 총운', '맑은 물에 씻긴 눈부신 보석처럼 순수하고 예민하며 뛰어난 직관과 영감을 지닌 기질입니다.', '신금의 날카로운 감각이 차가운 해수 상관을 만나 몹시 투명하고 비상한 두뇌 회전을 자랑합니다. 불결하거나 불합리한 것을 결코 용납하지 않는 결벽주의적 성향이 있으며 사람들의 이면을 꿰뚫어 보는 통찰력과 함께 뛰어난 언변으로 자신을 화려하게 뽐내는 외유내강의 표본입니다.', 70, true),
('day_pillar', '신해', 'career', '신해일주 · 직업', '직관력과 표현력을 발휘하는 기획, 교육, 예술, 문학, IT 및 상담 분야에 매우 적합합니다.', '금수쌍청의 맑은 기운으로 학문이나 문학, 예술 분야에서 창의적인 아이디어를 쏟아내며 대단한 능률을 보입니다. 상관의 화려한 화술을 바탕으로 사람을 가르치거나 설득하는 교육자, 언론인으로도 성공하기 쉬우며 예리한 분석력을 요구하는 데이터 처리 기획 업무에서도 두각을 나타냅니다.', 70, true),
('day_pillar', '신해', 'love', '신해일주 · 연애', '로맨틱하고 세련되게 다가가나 결점이 보이면 얼음장처럼 차갑게 돌아서는 냉정함이 있습니다.', '매력적인 외모와 다정다감한 성격으로 이성에게 인기가 많으며 분위기를 잘 리드합니다. 하지만 까다로운 이상형의 기준을 내세우며 상대방의 사소한 실수에도 깊게 상처를 받고 날카로운 비판을 서슴지 않으므로 상호 간의 부족함을 너그럽게 덮어주려는 노력이 원만한 관계에 필수적입니다.', 70, true),
('day_pillar', '신해', 'wealth', '신해일주 · 재물', '남다른 아이디어와 정교한 전문 기술을 통해 경제적 독립을 이루어 내는 실속파 흐름입니다.', '자신의 뛰어난 언변이나 특출난 자격증, 기술을 현금으로 직결시키는 수완이 비상합니다. 돈을 다루는 데 있어 불필요한 낭비를 극도로 꺼리며 계산이 정확해 손해 보는 짓을 하지 않지만 타인에게 베풀 때는 씀씀이가 커지기도 하므로 번 돈을 착실히 문서로 묶어두는 지혜가 필요합니다.', 70, true),
('day_pillar', '신해', 'health', '신해일주 · 건강', '몸이 차가워지기 쉬운 구조이므로 신장, 방광 건강과 심리적 안정에 유의하면 좋습니다.', '차가운 금과 물의 기운이 겹쳐 하복부가 냉해지기 쉽고 비뇨기 계통이나 생식기 기능이 약해질 우려가 있습니다. 완벽주의 성향 탓에 신경성 두통이나 불면증에 시달릴 수 있으니 평소 족욕이나 반신욕 등으로 체온을 올리고 마음을 편안하게 이완시키는 정적인 취미를 갖는 것이 유익합니다.', 70, true),
('day_pillar', '임자', 'general', '임자일주 · 총운', '거센 파도가 일렁이는 깊은 바다처럼 포용력이 넓고 융통성이 뛰어나나 속을 알 수 없는 기질입니다.', '임수와 자수가 만난 간여지동이자 양인의 구조로 천하를 삼킬 듯한 스케일과 강렬한 승부욕을 지녔습니다. 겉보기엔 부드럽고 다정다감해 환경 적응력이 뛰어나지만 내면에는 누구에게도 굽히지 않는 극강의 자존심과 고집이 있으며 한 번 화가 나면 쓰나미처럼 폭발하는 에너지를 품고 있습니다.', 70, true),
('day_pillar', '임자', 'career', '임자일주 · 직업', '강력한 추진력과 활동성을 요하는 군검경, 무역, 정치, 유통, 해운업 등에 훌륭하게 맞습니다.', '거대한 물의 기운으로 리더십이 탁월하여 조직의 수장이나 대규모 사업을 지휘할 때 눈부신 역량을 발휘합니다. 생사여탈권을 쥐는 공직이나 해외를 무대로 삼는 글로벌 유통, 무역 분야에서 압도적인 성취를 거두기 쉬우며 타인의 지시를 받기보다 독립적으로 판을 짤 때 능률이 치솟습니다.', 70, true),
('day_pillar', '임자', 'love', '임자일주 · 연애', '사람을 끄는 매력이 넘쳐 연애를 주도하나 소유욕이 강하고 감정 기복이 심한 편입니다.', '다정하고 세련된 화술로 상대방을 매혹하며 유쾌한 데이트를 이끌어가나 양인의 기운 탓에 자기중심적이고 상대를 통제하려는 성향이 표출될 수 있습니다. 연애에 있어서도 자존심을 굽히지 않아 마찰이 길어지기 쉬우니 상대방의 감정을 섬세하게 헤아리고 양보하는 미덕이 필요합니다.', 70, true),
('day_pillar', '임자', 'wealth', '임자일주 · 재물', '일확천금을 노리는 배포가 있어 굴곡이 크지만 결국 대규모 자산을 운용하는 대부호의 흐름입니다.', '작은 이익에 얽매이지 않고 큰 사업이나 투자에 뛰어들어 단숨에 막대한 부를 거머쥐는 능력이 출중합니다. 그러나 물이 흐르듯 돈이 쉽게 들어왔다 쉽게 나가는 기복이 심하므로 번 돈을 즉시 현금화하기 어려운 부동산이나 문서 형태로 묶어두는 보수적인 재산 관리가 부를 지키는 핵심입니다.', 70, true),
('day_pillar', '임자', 'health', '임자일주 · 건강', '수기가 지나치게 강해 심혈관계나 위장 장애, 신장 기능 불균형에 신경 쓰면 좋습니다.', '신체에 찬 기운이 넘쳐 혈액순환이 정체되거나 혈압에 무리가 갈 수 있으며 소화기가 예민해지기 쉬운 체질입니다. 찬 음식을 피하고 몸을 덥혀주는 식습관을 유지하며 땀을 충분히 배출하는 유산소 운동으로 기혈의 순환을 촉진하고 심리적인 화기를 안정시키는 것이 건강에 크게 이롭습니다.', 70, true),
('day_pillar', '계축', 'general', '계축일주 · 총운', '얼어붙은 겨울비처럼 맑고 순수하지만 목표를 향한 인내력과 집념이 무섭도록 끈질긴 기질입니다.', '계수의 부드러운 직관이 축토라는 차가운 흙에 스며든 백호살의 구조로 겉보기엔 매우 수더분하고 과묵합니다. 하지만 내면에는 편관의 날카로운 긴장감과 한 번 결심한 일은 밤을 새워서라도 해내고 마는 대단한 고집이 서려 있으며 남모를 고독감과 철학적 사유를 즐기는 외유내강형입니다.', 70, true),
('day_pillar', '계축', 'career', '계축일주 · 직업', '특수한 전문 지식과 끈기를 요하는 종교, 활인(의료, 상담), 교육, 기획 분야에 적합합니다.', '타인의 심리를 꿰뚫어보는 예리한 영감이 있어 심리 상담, 정신과 의사, 명리학 등의 분야에서 독보적인 두각을 나타냅니다. 남의 눈에 띄지 않는 곳에서 치밀하게 연구하거나 기획하는 업무에 강하며 불굴의 인내력으로 특수 자격증을 요구하는 전문직에서 사회적 존경과 부를 얻습니다.', 70, true),
('day_pillar', '계축', 'love', '계축일주 · 연애', '쉽게 곁을 내어주지 않고 무뚝뚝하지만 한 번 인연을 맺으면 변치 않는 헌신을 보여줍니다.', '상대를 오랜 시간 지켜보며 신뢰를 쌓아가는 신중함이 돋보이나 애정 표현이 몹시 서툴러 상대방이 차가움이나 답답함을 느낄 수 있습니다. 백호살의 영향으로 감정이 폭발할 때 극단적인 언행이 나올 수 있으니 평소 부드러운 대화로 스트레스를 풀고 서로의 마음을 확인하는 노력이 필수입니다.', 70, true),
('day_pillar', '계축', 'wealth', '계축일주 · 재물', '근검절약과 저축을 통해 보이지 않는 실물 자산을 묵직하게 쌓아가는 알짜배기 성향입니다.', '돈을 허투루 쓰는 낭비를 극도로 꺼리며 꼼꼼하게 실속을 챙기는 경제 관념이 탁월해 남몰래 커다란 부를 축적합니다. 무리한 사업 확장이나 투기보다는 흙 속에 물을 보관하듯 부동산, 땅, 자격증 등을 통해 차곡차곡 재산을 불려가는 보수적인 재테크 방식이 훗날 든든한 안정을 보장합니다.', 70, true),
('day_pillar', '계축', 'health', '계축일주 · 건강', '냉기가 뼛속까지 스며들기 쉬워 소화기 장애와 비뇨기 계통, 보온 관리에 유의하면 좋습니다.', '차가운 물과 언 땅이 만나 체온이 낮아지고 위장이 극도로 예민해져 소화 불량이나 신경성 위장병에 시달릴 우려가 큽니다. 찬 음식을 멀리하고 하복부를 늘 따뜻하게 덥히는 것이 중요하며 긴장된 근육을 풀어주는 온욕이나 가벼운 요가를 통해 신체의 혈액순환을 돕는 습관이 건강의 비결입니다.', 70, true),
('day_pillar', '갑인', 'general', '갑인일주 · 총운', '하늘 높이 솟은 거목처럼 스케일이 크고 독립심이 강하며 대의명분을 중시하는 곧은 기질입니다.', '갑목과 인목이 만난 간여지동의 구조로 추진력과 배포가 대단하여 한 번 마음먹은 일은 타협 없이 밀어붙입니다. 겉보기엔 몹시 당당하고 자존심이 세어 굽히는 법을 모르나 속에는 여린 동정심과 다정함을 품고 있어 약자에게 약하고 불의를 보면 참지 못하는 호탕한 성품을 지녔습니다.', 70, true),
('day_pillar', '갑인', 'career', '갑인일주 · 직업', '강력한 리더십과 주도권을 행사하는 정치, 교육, 무역, 사업 등 스케일 큰 분야에 훌륭하게 맞습니다.', '남의 밑에서 지시를 받는 조직 생활보다는 독립적으로 무리를 이끄는 수장이나 경영자로서 눈부신 역량을 발휘합니다. 사람을 통솔하고 가르치는 교육자, 큰 자본을 움직이는 사업가, 혹은 건록의 강한 기운을 살려 해외를 오가는 무역업에서 대단한 성취와 사회적 존경을 동시에 얻기 좋습니다.', 70, true),
('day_pillar', '갑인', 'love', '갑인일주 · 연애', '솔직하고 열정적으로 상대를 보호하려 하나 극강의 고집과 통제하려는 성향 탓에 마찰이 잦습니다.', '연애에 있어서도 주도권을 쥐려 하며 자신이 상대방을 책임지려는 듬직함을 보여줍니다. 하지만 자기주장이 워낙 강하고 남에게 지기 싫어하는 자존심 때문에 다툼이 발생하면 쉽게 물러서지 않아 상대를 지치게 할 수 있으므로 너그러운 양보와 부드러운 소통 방식을 의식적으로 길러야 합니다.', 70, true),
('day_pillar', '갑인', 'wealth', '갑인일주 · 재물', '안정적인 소액 저축보다는 큰 사업적 성취나 명예를 바탕으로 거대한 부를 일구는 흐름입니다.', '독립심과 자수성가의 기운이 강렬해 타인의 도움 없이도 নিজের 힘으로 큰 재물을 거머쥐는 능력이 출중합니다. 다만 기분파적인 지출이 있고 남에게 베풀기를 좋아해 돈이 흩어질 위험이 존재하므로 굴린 현금을 즉시 부동산 문서나 단단한 실물 자산으로 묶어두는 지혜가 부를 지키는 방어막입니다.', 70, true),
('day_pillar', '갑인', 'health', '갑인일주 · 건강', '에너지 발산이 몹시 커서 간장이나 신경계 질환, 위장 장애 관리에 신경 쓰면 좋습니다.', '목기가 지나치게 강해 토기를 극하는 구조상 위장이나 비장 기능이 억눌려 소화 불량에 시달리기 쉬운 체질입니다. 과로나 스트레스가 누적되면 간 기능이 떨어지거나 신경통이 올 수 있으니 충분한 수면을 취하고 무리한 활동 후에는 명상이나 휴식을 통해 마음의 화기를 차분하게 덜어내야 합니다.', 70, true),
('day_pillar', '을묘', 'general', '을묘일주 · 총운', '봄날의 푸른 초원처럼 생명력이 넘치고 환경 적응력이 뛰어나며 끈질긴 인내력을 지닌 기질입니다.', '을목과 묘목이 만난 간여지동으로 겉보기엔 부드럽고 다정다감하여 대인관계가 원만해 보이지만 내면에는 결코 꺾이지 않는 질긴 고집과 오기가 서려 있습니다. 사람들과 융화되면서도 치열한 경쟁 심리를 품고 있어 목표를 향해 치밀하게 파고드는 외유내강형의 전형적인 모습을 보여줍니다.', 70, true),
('day_pillar', '을묘', 'career', '을묘일주 · 직업', '섬세함과 끈기, 뛰어난 손재주를 발휘하는 디자인, 교육, 기획, 전문 기술 분야에 적합합니다.', '뛰어난 눈치와 미적 감각을 타고나 인테리어, 패션, 미용 등 감각을 요구하는 분야에서 탁월한 성과를 냅니다. 남들과 부드럽게 협력하면서도 자신의 이익을 챙기는 수완이 좋아 기획 업무나 남을 가르치는 교육계통, 혹은 특수 면허를 요구하는 전문 기술직에서 안정적인 성공 가도를 달립니다.', 70, true),
('day_pillar', '을묘', 'love', '을묘일주 · 연애', '세심하게 상대를 챙기며 다정하나 자존심이 강하고 질투심이나 집착이 드러날 수 있습니다.', '부드럽고 매너로 이성에게 인기가 많으며 연인에게 헌신적으로 정을 쏟아 안정적인 관계를 이끌어갑니다. 하지만 내면의 경쟁심 탓에 은근히 상대방을 통제하려 하거나 서운한 감정을 혼자 삭이다 엉뚱하게 폭발할 우려가 있으므로 진솔한 대화를 통해 신뢰를 확인하고 집착을 버리는 연습이 중요합니다.', 70, true),
('day_pillar', '을묘', 'wealth', '을묘일주 · 재물', '치밀한 계산 능력과 끈기를 바탕으로 낭비 없이 알뜰하게 자산을 쌓아 올리는 실속파입니다.', '큰 모험을 걸기보다는 자신이 가진 섬세한 기술과 자격을 바탕으로 차곡차곡 재산을 모아가는 흐름을 선호합니다. 돈을 다루는 데 있어 매우 현실적이고 꼼꼼하여 불필요한 지출을 철저히 막아내며 시간이 흐를수록 부동산이나 전문 지식 재산권을 통해 조용히 알부자로 거듭나는 유리한 구조입니다.', 70, true),
('day_pillar', '을묘', 'health', '을묘일주 · 건강', '스트레스를 내면으로 삭여 간과 소화기 기능에 무리가 갈 수 있으니 심리적 안정이 필요합니다.', '목기가 강하게 뭉쳐 흙의 기운을 억누르므로 위염이나 신경성 대장염 등 소화기 계통이 매우 예민해지기 쉽습니다. 사람들과의 관계에서 오는 스트레스를 풀지 못하면 간 피로도가 높아지고 편두통에 시달릴 수 있으니 긍정적인 마음가짐을 갖고 가벼운 유산소 운동으로 긴장을 풀어주는 것이 이롭습니다.', 70, true),
('day_pillar', '병진', 'general', '병진일주 · 총운', '비옥한 대지 위를 비추는 밝은 태양처럼 포용력이 넓고 명랑하며 활동성이 왕성한 기질입니다.', '병화의 화려한 열정과 진토의 스케일 큰 식신 기운이 만나 어떠한 환경에서도 두각을 나타내는 다재다능함을 지녔습니다. 겉보기엔 대단히 낙천적이고 사람들에게 베풀기를 좋아해 인기가 많으나 속으로는 예리한 통찰력과 굽히기 싫어하는 강한 자존심을 숨기고 있는 외유내강의 성향입니다.', 70, true),
('day_pillar', '병진', 'career', '병진일주 · 직업', '화려한 언변과 기획력을 살려 교육, 방송, 언론, 영업, 디자인 분야 등에 훌륭하게 맞습니다.', '식신의 유창한 화술과 사람을 끌어당기는 매력을 발휘해 남을 가르치는 강사나 아나운서, 혹은 마케팅 전문가로서 최고의 능률을 보입니다. 창의적인 아이디어가 풍부하여 기획이나 디자인 영역에서도 독창적인 성과를 내며 대인관계가 원만해 규모가 큰 영업직에서도 리더로 빠르게 성장할 수 있습니다.', 70, true),
('day_pillar', '병진', 'love', '병진일주 · 연애', '다정다감하게 연애를 주도하며 매력이 넘치나 변덕이 심하고 감정선이 쉽게 흔들리는 편입니다.', '센스 있고 로맨틱한 데이트를 이끌어가며 상대방을 즐겁게 해주는 능력이 탁월해 이성에게 몹시 호감을 줍니다. 하지만 이상형의 잣대가 은근히 높고 구속받는 것을 극도로 꺼려 관계가 지루해지면 금세 흥미를 잃을 수 있으니 한 사람에게 진지하게 헌신하고 신뢰를 쌓으려는 책임감이 꼭 필요합니다.', 70, true),
('day_pillar', '병진', 'wealth', '병진일주 · 재물', '탁월한 친화력과 정보력을 바탕으로 다방면에서 끊임없이 넉넉한 수익을 창출해 내는 흐름입니다.', '평생 먹을 복이 마르지 않는 식신의 구조답게 자신의 아이디어를 즉각적인 재물로 연결하는 재주가 대단히 뛰어납니다. 다만 사람들과 어울리기를 좋아해 유흥이나 과시성 지출로 돈이 흩어지기 쉬우므로 벌어들인 재물을 진토라는 흙의 창고에 즉각 부동산 문서로 묶어두는 지혜가 부를 지키는 열쇠입니다.', 70, true),
('day_pillar', '병진', 'health', '병진일주 · 건강', '에너지 소모가 커서 심장 및 혈압 문제, 소화기 장애 등에 유의하고 수분을 챙기면 좋습니다.', '열기를 끊임없이 외부로 발산하다 보니 쉽게 피로해지거나 심장에 무리가 오고 혈압이 불안정해질 우려가 큽니다. 위장에 열이 누적되어 소화 불량을 겪기 쉬운 체질이므로 맵고 짠 자극적인 음식을 삼가고 명상이나 수영 등 몸의 화기를 식혀줄 수 있는 차분한 활동을 일상화하는 것이 바람직합니다.', 70, true),
('day_pillar', '정사', 'general', '정사일주 · 총운', '밤하늘을 태울 듯 타오르는 용광로처럼 열정적이고 활동적이며 승부욕이 대단히 강한 기질입니다.', '정화와 사화가 만난 간여지동이자 제왕의 기운으로 겉보기엔 부드럽고 예의 발라 보이지만 내면엔 그 누구에게도 지기 싫어하는 극강의 고집과 불꽃 같은 투지를 감추고 있습니다. 두뇌 회전이 몹시 빠르고 상황 판단력이 예리하며 한 번 목표를 정하면 타협 없이 돌진하는 강렬함을 보여줍니다.', 70, true),
('day_pillar', '정사', 'career', '정사일주 · 직업', '강한 추진력과 독립성을 요하는 특수 기술, 군검경, 언론, 디자인 및 대형 사업 분야에 적합합니다.', '누군가의 밑에서 순응하기보다는 독자적으로 역량을 뽐내는 프리랜서나 전문 기술직, 벤처 사업가로서 대단한 성과를 냅니다. 남의 시선을 사로잡는 뛰어난 감각으로 방송, 미용, 패션계에서 두각을 나타내며 겁재의 경쟁 심리를 활용해 생살여탈권을 쥐는 공직에서도 압도적인 능률을 발휘하기 좋습니다.', 70, true),
('day_pillar', '정사', 'love', '정사일주 · 연애', '열정적이고 헌신적으로 상대를 대하나 지배하려는 성향과 불같은 화를 조절하기 어렵습니다.', '연애 시 솔직하고 화끈하게 감정을 표현하며 상대방을 챙기는 따뜻함을 지녔지만 질투심과 소유욕이 워낙 강해 사소한 다툼이 큰 싸움으로 번질 위험이 큽니다. 내 뜻대로 관계를 이끌어가려는 통제욕을 버리고 상대의 감정을 섬세하게 헤아려 한 발짝 물러서는 유연한 태도를 기르는 것이 필수적입니다.', 70, true),
('day_pillar', '정사', 'wealth', '정사일주 · 재물', '스케일 큰 승부사 기질로 거대한 부를 노리지만 잦은 경쟁과 기복으로 재산이 흩어지기 쉽습니다.', '치열한 경쟁 속에서 남보다 앞서나가 단숨에 큰 수익을 거머쥐는 수완이 출중하나 주변 사람들과 얽혀 돈이 빠져나가는 겁재의 기운을 주의해야 합니다. 무리한 투자나 동업은 철저히 피하고 번 돈을 즉시 현금화하기 힘든 부동산, 건물, 특수 자격증 형태로 묶어두는 묵직한 자산 관리가 최선입니다.', 70, true),
('day_pillar', '정사', 'health', '정사일주 · 건강', '화기가 극에 달해 심장이나 시력, 혈압 및 호흡기 질환 관리에 각별히 신경 쓰면 좋습니다.', '열기가 뭉쳐 혈액순환에 불균형이 오고 안구 건조증이나 신경 쇠약 등에 쉽게 노출되는 체질입니다. 분노를 참지 못하면 심장에 무리가 갈 수 있으므로 평소 수분을 충분히 보충하고 등산이나 요가 등 몸과 마음의 화기를 차분히 가라앉히는 이완 활동을 꾸준히 실천하는 것이 장기적인 건강의 척도입니다.', 70, true),
('day_pillar', '무오', 'general', '무오일주 · 총운', '한여름의 화산처럼 장엄하고 위엄이 넘치며 그 속에 폭발적인 에너지를 감춘 강력한 기질입니다.', '무토라는 거대한 산이 오화라는 뜨거운 불을 품은 양인살과 정인의 구조로 엄청난 인내력과 함께 타의 추종을 불허하는 주관을 자랑합니다. 겉보기엔 무뚝뚝하고 점잖아 보이지만 내면엔 불의를 용납하지 않는 극단적인 결단력과 굽히지 않는 고집이 활화산처럼 끓어오르는 외강내강의 전형입니다.', 70, true),
('day_pillar', '무오', 'career', '무오일주 · 직업', '독립적이고 스케일 큰 통솔력을 발휘하는 정치, 군검경, 종교, 부동산, 교육 분야에 잘 맞습니다.', '조직의 말단에 머물기보다는 거대한 프로젝트를 지휘하거나 무리를 이끄는 수장으로서 압도적인 리더십을 발휘합니다. 학문적인 깊이를 갖춰 대학 교수나 종교인으로 큰 명예를 얻기도 하며 극강의 추진력을 무기로 생사여탈권을 다루는 공직이나 대형 토목 사업 등에서 눈부신 성취를 거두기 좋습니다.', 70, true),
('day_pillar', '무오', 'love', '무오일주 · 연애', '책임감이 강하고 듬직하게 헌신하지만 자존심이 워낙 세고 표현이 서툴러 갈등이 잦습니다.', '가벼운 만남을 극도로 꺼리고 한 번 맺은 배우자를 묵묵히 지켜내려는 태도가 돋보이나 무뚝뚝한 언행으로 상대에게 무심하게 비칠 수 있습니다. 타협을 모르고 자신의 뜻을 강요하려는 통제 성향이 강하므로 상대방의 감정에 귀를 기울이고 다정하게 양보하는 훈련이 원만한 가정을 유지하는 비결입니다.', 70, true),
('day_pillar', '무오', 'wealth', '무오일주 · 재물', '큰 사업적 배포나 전문 자격증을 바탕으로 부동산을 통해 막대한 부를 묵직하게 쌓아가는 흐름입니다.', '현금을 직접 굴리는 얄팍한 상술보다는 자신의 높은 명예나 뛰어난 학위, 전문 면허를 통해 사회적 지위를 얻고 그에 비례해 경제적 안정을 거머쥐는 구조입니다. 흙의 든든함을 살려 땅이나 건물 등 보이지 않는 큰 문서 자산에 투자할 때 잠재된 엄청난 재물복이 폭발적인 성과를 냅니다.', 70, true),
('day_pillar', '무오', 'health', '무오일주 · 건강', '열기가 심하게 뭉쳐 심혈관계 및 소화기 장애, 피부 건조증 등의 건강 관리에 유의하면 좋습니다.', '건조하고 뜨거운 화토의 기운으로 위장에 열이 쌓여 위염이나 변비에 취약해지고 고혈압이나 심장 질환에 노출될 우려가 큽니다. 스트레스를 속으로 고집스럽게 안고 가지 말고 땀을 배출하는 유산소 운동으로 열을 식히며 충분한 수분 섭취와 신선한 채소 위주의 식습관을 유지하면 좋습니다.', 70, true),
('day_pillar', '기미', 'general', '기미일주 · 총운', '여름날의 메마른 흙처럼 인내심이 질기고 독립심이 강하며 환경에 흔들리지 않는 묵직한 기질입니다.', '기토와 미토가 만난 간여지동의 구조로 겉보기엔 매우 수더분하고 다정다감하여 대인관계가 유연해 보이지만 내면에는 그 누구도 꺾지 못할 대단한 고집과 승부욕이 서려 있습니다. 남에게 의지하기보다 스스로 고난을 딛고 일어서는 자수성가형의 끈기와 직관력이 특히 돋보이는 성향입니다.', 70, true),
('day_pillar', '기미', 'career', '기미일주 · 직업', '뛰어난 인내력과 치밀함을 요하는 전문 기술, 부동산, 종교, 활인(의료, 상담) 분야에 적합합니다.', '한 우물을 파는 장인 정신이 있어 남들이 꺼리는 어렵고 특수한 기술직이나 연구직에서 탁월한 성과를 거둡니다. 사람의 심리를 꿰뚫어 보는 편관의 예민함을 살려 심리 상담가나 역술인, 종교인으로도 대성하기 쉬우며 땅의 기운을 다루는 건축, 부동산 분야에서도 흔들림 없는 안정을 누리기 좋습니다.', 70, true),
('day_pillar', '기미', 'love', '기미일주 · 연애', '신중하고 듬직하게 상대를 챙기나 극도로 강한 자존심 탓에 한 번 틀어지면 몹시 냉정해집니다.', '인연을 가볍게 맺지 않고 배우자에게 깊은 의리를 보여주나 무뚝뚝한 표현 방식과 꺾이지 않는 고집 때문에 상대방이 억압감을 느낄 수 있습니다. 겉으로는 포용하는 척해도 속마음을 쌓아두다 폭발하는 경향이 있으므로 평소 부드러운 대화로 감정을 솔직하게 교류하는 연습이 몹시 중요합니다.', 70, true),
('day_pillar', '기미', 'wealth', '기미일주 · 재물', '근검절약과 치밀한 계획을 바탕으로 부동산이나 땅을 통해 묵직하게 자산을 불려 가는 실속파입니다.', '돈을 허투루 쓰는 낭비를 극도로 싫어하며 꼼꼼하게 실속을 챙기는 경제 관념이 뛰어나 중년 이후 조용히 커다란 부를 축적하는 경우가 많습니다. 화려한 투기성 상업보다는 메마른 흙 속에 재물을 보관하듯 문서나 덩치가 큰 실물 자산으로 단단히 묶어두는 보수적인 재테크가 재산을 지키는 핵심입니다.', 70, true),
('day_pillar', '기미', 'health', '기미일주 · 건강', '조열한 기운 탓에 위염, 변비 등 소화기 질환이나 관절 건강 유지에 각별히 신경 쓰면 좋습니다.', '건조한 흙의 겹침으로 위장에 열이 뭉쳐 소화 능력이 둔화되고 피부 건조증에 시달리기 쉬운 체질입니다. 화를 안으로 삭이다 신경성 위장병이 올 수 있으니 맵고 짠 음식을 멀리하고 물을 자주 섭취하며 요가나 가벼운 스트레칭으로 굳은 관절과 근육을 유연하게 풀어주는 것이 건강에 유익합니다.', 70, true),
('day_pillar', '경신', 'general', '경신일주 · 총운', '제련된 강철검처럼 극강의 결단력과 용맹함을 갖추고 불의에 굽히지 않는 날카로운 기질입니다.', '경금과 신금이 만난 간여지동이자 건록의 구조로 천하를 압도하는 카리스마와 승부욕을 자랑합니다. 매사에 맺고 끊음이 얼음장처럼 명확하고 한 번 목표를 정하면 타협 없이 돌진하는 강철 같은 의지를 지녔습니다. 겉은 차갑고 냉정해 보이지만 내면에는 깊은 의리와 정의감이 끓어오르는 의협심 덩어리입니다.', 70, true),
('day_pillar', '경신', 'career', '경신일주 · 직업', '강력한 통솔력과 결단력을 발휘하는 군검경, 정치, 스포츠, 대형 사업 분야에 매우 적합합니다.', '누군가의 밑에서 순응하기보다는 독자적으로 조직을 지휘하고 굵직한 결정을 내릴 때 탁월한 역량을 발휘합니다. 생사여탈권을 쥐는 공직이나 법조계, অথবা 극한의 에너지를 뿜어내는 스포츠계 등 스케일이 크고 독립적인 활동이 보장되는 무대에서 압도적인 성취와 명예를 거머쥐기 좋은 구조입니다.', 70, true),
('day_pillar', '경신', 'love', '경신일주 · 연애', '책임감 있게 헌신하나 자기주장이 너무 강하고 통제하려는 성향 탓에 갈등이 생기기 쉽습니다.', '가벼운 만남을 극도로 꺼리고 진지한 연애를 지향하며 한 번 내 사람이라 여기면 목숨을 걸고 보호하려는 듬직함이 있습니다. 하지만 워낙 굽힐 줄 모르는 자존심과 타인을 훈계하려는 뻣뻣한 태도로 인해 상대가 지칠 우려가 크므로 의식적으로 부드러운 화법을 구사하고 양보하는 포용력을 꼭 길러야 합니다.', 70, true),
('day_pillar', '경신', 'wealth', '경신일주 · 재물', '안정적인 소액 저축보다 큰 명예와 스케일 큰 사업적 결단을 통해 거대한 부를 쟁취하는 성향입니다.', '독립심이 강해 자수성가로 큰 재물을 일구는 능력이 출중하며 푼돈보다는 굵직한 프로젝트나 투자에서 단숨에 막대한 수익을 올리는 데 재능이 탁월합니다. 다만 금속성의 차가운 결단력이 자칫 무리한 승부수로 이어져 손실을 볼 수 있으므로 굴린 현금을 즉시 안전한 실물 부동산으로 묶어두는 지혜가 필요합니다.', 70, true),
('day_pillar', '경신', 'health', '경신일주 · 건강', '금기가 지나치게 뭉쳐 폐나 호흡기, 대장 기능 및 뼈 관절 질환 관리에 신경 쓰면 좋습니다.', '강인한 체력을 과신하여 몸을 험하게 다루다 관절이나 인대에 무리가 오기 쉬우며 목기가 억눌려 간 피로도가 급격히 높아질 수 있는 체질입니다. 과로와 스트레스를 피하고 긴장된 근육을 풀어주는 온욕이나 부드러운 스트레칭을 생활화하며 맑은 공기를 쐬어 폐를 보호하는 것이 건강 유지의 비결입니다.', 70, true),
('day_pillar', '신유', 'general', '신유일주 · 총운', '정교하게 세공된 눈부신 다이아몬드처럼 극도로 예리하고 섬세하며 맺고 끊음이 칼같은 기질입니다.', '신금과 유금이 만난 간여지동으로 세상의 오염을 거부하는 투명한 순수함과 완벽주의를 고집합니다. 두뇌 회전이 대단히 빠르고 겉보기엔 부드럽고 세련된 매력을 풍기지만 내면에는 그 누구도 침범할 수 없는 날카로운 잣대와 차가운 비판력을 품고 있어 타인과 쉽게 타협하지 않는 극강의 자존심을 뽐냅니다.', 70, true),
('day_pillar', '신유', 'career', '신유일주 · 직업', '최고의 정밀함과 날카로움을 요하는 의료, 법조, 회계, IT 기술 및 디자인 분야에 훌륭하게 맞습니다.', '세밀한 부분 하나까지 놓치지 않는 완벽주의로 의사, 세무사, 데이터 분석가 등 고도의 전문성을 필요로 하는 직무에서 독보적인 능률을 올립니다. 예술적 감각 또한 대단히 뛰어나 미용, 귀금속 세공, 패션 디자인 분야에서도 자신만의 세련된 솜씨로 인정받고 대중적인 성공을 쟁취하기 좋습니다.', 70, true),
('day_pillar', '신유', 'love', '신유일주 · 연애', '세련된 매너로 헌신하지만 이상형의 잣대가 몹시 높아 결점이 보이면 얼음장처럼 차가워집니다.', '깔끔하고 매력적인 외모로 이성의 호감을 쉽게 얻으며 연인에게 다정하게 대하지만 내심 상대방의 능력과 도덕성을 까다롭게 평가합니다. 작은 실수에도 깊게 실망하고 날카로운 독설로 상처를 주거나 뒤돌아서는 단호함이 있으므로 서로의 부족함을 너그럽게 덮어주려는 따뜻한 포용력이 원만한 관계에 필수적입니다.', 70, true),
('day_pillar', '신유', 'wealth', '신유일주 · 재물', '치밀한 계산 능력과 낭비 없는 절약 정신을 바탕으로 알뜰하게 실속을 챙기며 부를 축적하는 흐름입니다.', '돈을 허투루 쓰는 법이 결코 없으며 재물의 흐름을 파악하는 감각이 탁월해 남몰래 튼튼한 경제적 기반을 다지는 알부자 성향이 강합니다. 위험 부담이 큰 사업보다는 자신의 특출난 기술이나 전문 자격증을 통해 안정적이고 묵직한 수익을 창출하며 현금을 묶어두는 꼼꼼한 자산 관리에 몹시 능합니다.', 70, true),
('day_pillar', '신유', 'health', '신유일주 · 건강', '금기가 극도로 강해 호흡기 계통이나 대장 기능, 신경성 두통 관리에 유의하면 좋습니다.', '예민한 완벽주의 탓에 늘 신경이 곤두서 있어 불면증이나 편두통, 만성 피로에 시달릴 우려가 큽니다. 차갑고 건조한 기운이 겹쳐 폐나 기관지가 약해지기 쉬우니 평소 따뜻한 차를 마시고 다도나 가벼운 걷기 명상 등으로 마음의 짐을 내려놓으며 심리적인 긴장을 이완시키는 것이 장기적인 건강에 큰 도움이 됩니다.', 70, true),
('day_pillar', '임술', 'general', '임술일주 · 총운', '깊은 산속의 거대한 호수처럼 속을 알 수 없는 포용력과 비상한 통찰력, 강한 권력욕을 지닌 기질입니다.', '임수와 조열한 술토가 만난 백호살과 괴강살의 구조로 겉보기엔 부드럽고 다정다감하여 대인관계가 유연하지만 내면엔 천하를 호령하려는 극강의 스케일과 승부욕이 끓어오릅니다. 타인의 마음을 꿰뚫어 보는 예리한 직관이 돋보이며 위기 상황일수록 더욱 맹렬하게 돌진하는 불굴의 추진력을 보여줍니다.', 70, true),
('day_pillar', '임술', 'career', '임술일주 · 직업', '생살여탈권을 쥐고 권력을 행사하는 군검경, 법조, 무역, 대형 부동산 및 사업 분야에 매우 적합합니다.', '뛰어난 통솔력과 결단력을 갖춰 조직의 말단에 순응하기보다 독립적으로 큰 판을 짜고 리드할 때 눈부신 역량을 발휘합니다. 사람을 통제하는 공직이나 수사기관, 혹은 큰 자본이 오가는 건축, 유통업에서 두각을 나타내며 천문성의 직관을 살려 활인업이나 철학 분야에서도 깊이 있는 성과를 이끌어냅니다.', 70, true),
('day_pillar', '임술', 'love', '임술일주 · 연애', '책임감이 대단히 강하고 상대를 든든히 지켜내려 하나 지배하려는 고집과 무뚝뚝함이 갈등을 낳습니다.', '진지하고 묵직하게 연애에 임하며 내 사람이라 생각하면 모든 것을 바쳐 보호하려는 의리가 넘칩니다. 그러나 자신의 뜻대로 관계를 쥐고 흔들려는 통제욕이 강해 상대방이 억압을 느끼기 쉬우며 한 번 화가 나면 무섭게 폭발하므로 상대의 감정을 섬세하게 살피고 져주는 다정한 포용력을 의식적으로 훈련해야 합니다.', 70, true),
('day_pillar', '임술', 'wealth', '임술일주 · 재물', '큰 스케일의 사업이나 부동산을 통해 거대한 부를 쟁취하지만 굴곡 또한 크게 나타나는 대부호의 흐름입니다.', '푼돈에 연연하지 않는 배포와 위기를 기회로 바꾸는 기개가 돋보여 한 번 흐름을 타면 상상을 초월하는 막대한 재산을 거머쥡니다. 지장간에 재물과 권력을 모두 품어 재물운이 강력하나 무리한 승부수로 재산이 흩어질 위험도 존재하므로 번 돈을 즉시 흙 속의 문서나 땅으로 단단히 묶어두는 묵직한 관리가 필수적입니다.', 70, true),
('day_pillar', '임술', 'health', '임술일주 · 건강', '조열한 흙에 물이 마르기 쉬워 비뇨기 계통이나 신장, 위장 및 혈압 건강 관리에 신경 쓰면 좋습니다.', '에너지를 한꺼번에 폭발적으로 쏟아붓다 보니 혈압이 불안정해지고 신장의 수분 대사가 원활하지 않아 붓기나 피로감에 쉽게 노출되는 체질입니다. 과음과 과식을 철저히 경계하고 위장에 부담을 주지 않는 식습관을 유지하며 땀을 충분히 배출하는 규칙적인 유산소 운동으로 기혈의 흐름을 돕는 것이 몹시 이롭습니다.', 70, true),
('day_pillar', '계해', 'general', '계해일주 · 총운', '끝없이 흐르는 광활한 바다처럼 포용력이 압도적이고 두뇌 회전이 비상하며 유연성을 갖춘 기질입니다.', '계수와 해수가 만난 간여지동이자 제왕의 기운으로 겉보기엔 한없이 부드럽고 융통성이 넘쳐 누구와도 잘 어울립니다. 하지만 내면에는 그 무엇으로도 가둬둘 수 없는 극강의 고집과 극도의 예리한 직관력을 감추고 있어 맺고 끊음이 확실하며 남에게 결코 굽히지 않는 외유내강의 강력한 스케일을 보여줍니다.', 70, true),
('day_pillar', '계해', 'career', '계해일주 · 직업', '깊은 지혜와 독립성을 요하는 무역, 기획, 교육, 활인(의료, 상담) 및 IT 분야에 훌륭하게 맞습니다.', '뛰어난 통찰력과 정보 수집 능력을 갖춰 학자, 연구원, 데이터 기획 등 깊이 있는 지식을 다루는 직무에서 최고의 능률을 올립니다. 물의 흐름처럼 구속받기 싫어해 자유로운 환경이나 해외를 넘나드는 유통업, 외교에서 역량이 빛나며 사람의 마음을 치유하는 심리학이나 명리학 분야에서도 확고한 전문성을 다집니다.', 70, true),
('day_pillar', '계해', 'love', '계해일주 · 연애', '다정하고 낭만적으로 헌신하지만 간섭을 극도로 싫어하고 자기중심적인 고집이 강해 마찰이 빚어집니다.', '사람을 편안하게 해주는 매력으로 연애를 부드럽게 이끌어가나 제왕의 기운 탓에 상대방의 조언을 듣지 않고 제멋대로 관계를 주도하려는 성향이 짙습니다. 속마음을 잘 드러내지 않으면서도 의심이 많아 예민하게 굴 수 있으므로 서로의 프라이버시를 존중하면서도 진솔한 대화로 깊은 신뢰를 쌓아가는 노력이 중요합니다.', 70, true),
('day_pillar', '계해', 'wealth', '계해일주 · 재물', '탁월한 정보력과 전문 지식을 무기로 끊임없이 활동하며 넉넉한 부를 쟁취하는 능력 있는 흐름입니다.', '남들이 보지 못하는 흐름을 정확히 꿰뚫어보는 감각이 대단히 출중해 지적 재산권이나 유통을 통해 단숨에 큰 수익을 창출해 냅니다. 다만 지나치게 큰 물줄기는 재물을 한곳에 모아두기 어렵게 만들 수 있으므로 번 돈을 즉각 부동산이나 안정적인 자격증 등 물이 스며들 수 있는 실물 문서로 묶어두는 꼼꼼한 관리가 필수적입니다.', 70, true),
('day_pillar', '계해', 'health', '계해일주 · 건강', '수기가 과도하게 넘쳐 신장 및 방광 건강과 심혈관계, 위장 장애 관리에 각별히 유의하면 좋습니다.', '신체에 찬 기운이 맴돌아 혈액순환이 정체되기 쉽고 하복부가 냉해져 비뇨기나 생식기 계통이 약해질 우려가 큰 체질입니다. 스트레스를 속으로 삭여 신경성 위장병에 시달릴 수 있으니 평소 족욕이나 반신욕으로 체온을 따뜻하게 높이고 땀을 내는 운동으로 수분의 정체를 풀어주며 몸의 화기를 채워주는 것이 건강 유지에 이롭습니다.', 70, true)
